import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    static BufferedReader br;

    public static void main(String[] args) throws IOException{
        br = new BufferedReader(new InputStreamReader(System.in));
        long[] nm = longs();
        long n = nm[0];
        long m = nm[1];
        if (n > m) {
            long tmp = n;
            n = m;
            m = tmp;
        }

        long sol = 0;

        if (m < 3) {
            System.out.println(sol);
            return;
        }

        if (n == 1) {
            sol = m % 6;
            if (sol > 3) sol = 6 - sol;
            System.out.println(m - sol);
            return;
        }

        if (n == 2) {
            sol = m * n;
            if (m == 3) sol = 4;
            if (m == 7) sol = 12;
        } else if (n == 3) {
            sol = m * n;
            if (m % 2 == 1) sol -= 1;
        } else {
            if (m % 2 == 1 && n % 2 == 1) sol = m * n - 1;
            else sol = m * n;
        }

        System.out.println(sol);
    }

    static int[] ints() throws IOException {
        String[] line = br.readLine().split(" ");
        int[] ints = new int[line.length];
        for (int i = 0; i < line.length; i++) ints[i] = Integer.parseInt(line[i]);
        return ints;
    }

    static long[] longs() throws IOException {
        String[] line = br.readLine().split(" ");
        long[] longs = new long[line.length];
        for (int i = 0; i < line.length; i++) longs[i] = Long.parseLong(line[i]);
        return longs;
    }

    static double[] doubles() throws IOException {
        String[] line = br.readLine().split(" ");
        double[] doubles = new double[line.length];
        for (int i = 0; i < line.length; i++) doubles[i] = Double.parseDouble(line[i]);
        return doubles;
    }

}

